def analyze(nums: list) -> dict:
    if not nums:
        return {'count': 0, 'total': 0, 'avg': 0, 'max': None, 'min': None}
    total = sum(nums)
    return {
        'count': len(nums),
        'total': total,
        'avg': round(total / len(nums), 2),
        'max': max(nums),
        'min': min(nums),
    }

stats = analyze([88, 92, 76, 100])
print(stats)
print(analyze([]))
